wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(4002330)
,p_name=>'Eligible Users'
,p_static_id=>'eligible-users'
,p_title=>'Eligible Users'
,p_template=>2103954283454391425
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select apex_item.hidden(1, u.ebs_user_name) ||',
'       apex_escape.html(',
'         u.ebs_user_name ||',
'         case when u.local_user_email is not null then '' ('' || u.local_user_email || '')'' end',
'       ) user_name,',
'       u.full_name full_name,',
'       case when u.enabled_yn = ''N'' then ''Disabled (TMS)''',
'            when upper(nvl(w.account_locked, ''NO'')) = ''YES'' then ''Enabled (Local Locked)''',
'            else ''Enabled'' end account_status,',
'       case when exists (',
'              select 1',
'                from xx_tms_user_access x',
'               where x.application_code = :P11_APPLICATION_CODE',
'                 and x.user_name in (lower(u.ebs_user_name), nvl(u.local_user_email, lower(u.ebs_user_name)))',
'            ) then ''Yes'' else ''No'' end currently_enabled,',
'       apex_item.checkbox2(',
'         2,',
'         u.ebs_user_name,',
'         case when exists (',
'                select 1',
'                  from xx_tms_user_access x',
'                 where x.application_code = :P11_APPLICATION_CODE',
'                   and x.user_name in (lower(u.ebs_user_name), nvl(u.local_user_email, lower(u.ebs_user_name)))',
'              ) then ''checked="checked"'' end,',
'         null,',
'         null,',
'         ''access_'' || ora_hash(u.ebs_user_name),',
'         ''Access enabled for '' || u.ebs_user_name',
'       ) access_enabled',
'  from xx_tms_users u',
'  left join apex_workspace_apex_users w',
'    on lower(w.user_name) = u.local_user_email',
' where :P11_APPLICATION_CODE is not null',
'   and u.is_console_admin_yn = ''N''',
' order by u.ebs_user_name'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P11_APPLICATION_CODE'
,p_lazy_loading=>false
,p_query_row_template=>2542081983073888486
,p_query_num_rows=>500
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'SHOW_ALL'
,p_csv_output=>'Y'
,p_csv_output_link_text=>'Download'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
