wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(4003040)
,p_name=>'Usage Summary'
,p_static_id=>'usage-summary'
,p_title=>'Usage Summary'
,p_template=>2103954283454391425
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select metric, value',
'  from (',
'    select 1 metric_order, ''Unique Users'' metric,',
'           to_char(count(distinct apex_user)) value',
'      from apex_workspace_activity_log',
'     where application_id = :P20_APPLICATION_ID',
'       and view_date >= trunc(sysdate) - nvl(to_number(:P20_DAYS), 7) + 1',
'    union all',
'    select 2, ''Page Views'', to_char(count(*))',
'      from apex_workspace_activity_log',
'     where application_id = :P20_APPLICATION_ID',
'       and view_date >= trunc(sysdate) - nvl(to_number(:P20_DAYS), 7) + 1',
'    union all',
'    select 3, ''Distinct Sessions'', to_char(count(distinct apex_session_id))',
'      from apex_workspace_activity_log',
'     where application_id = :P20_APPLICATION_ID',
'       and view_date >= trunc(sysdate) - nvl(to_number(:P20_DAYS), 7) + 1',
'    union all',
'    select 4, ''Application Errors'',',
'           to_char(nvl(sum(case when error_message is not null then 1 else 0 end), 0))',
'      from apex_workspace_activity_log',
'     where application_id = :P20_APPLICATION_ID',
'       and view_date >= trunc(sysdate) - nvl(to_number(:P20_DAYS), 7) + 1',
'    union all',
'    select 5, ''Average Response Seconds'',',
'           to_char(round(nvl(avg(elapsed_time), 0), 3), ''FM9999990D000'')',
'      from apex_workspace_activity_log',
'     where application_id = :P20_APPLICATION_ID',
'       and view_date >= trunc(sysdate) - nvl(to_number(:P20_DAYS), 7) + 1',
'  )',
' order by metric_order'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P20_APPLICATION_ID,P20_DAYS'
,p_lazy_loading=>false
,p_query_row_template=>2542081983073888486
,p_query_num_rows=>20
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'SHOW_ALL'
,p_csv_output=>'Y'
,p_csv_output_link_text=>'Download'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'Y'
);
